import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { MantineProvider } from '@mantine/core/lib/core/MantineProvider/MantineProvider';

const root = ReactDOM.createRoot(document.getElementById('root') as HTMLElement);

root.render(
    <React.StrictMode>
        <MantineProvider
          theme={{
            primaryColor: "blue",
          }}
        >
            <App />
        </MantineProvider>
    </React.StrictMode>
);
